// ✅ Normalize Supabase GET response for user lookup

const items = $input.all();

if (!items.length) {
  // No data at all from Supabase node
  return [{ json: {} }];
}

let data = items[0].json;

// Supabase typically returns an array of rows
if (Array.isArray(data)) {
  if (data.length === 0) {
    // Empty array → no match
    return [{ json: {} }];
  } else {
    // Return first record
    return [{ json: data[0] }];
  }
}

// Already an object (some Supabase nodes do this)
if (typeof data === 'object' && data !== null) {
  return [{ json: data }];
}

// Default fallback
return [{ json: {} }];

// ------------------------------------------------------------
// Parse Assistant Response
// Compatible with OpenAI Responses API
// ------------------------------------------------------------

let response = null;

// 1. Preferred field (many n8n versions expose this directly)
if (typeof $json.output_text === "string") {
  response = $json.output_text.trim();
}

// 2. Standard Responses API output array
if (
  !response &&
  Array.isArray($json.output)
) {
  for (const item of $json.output) {
    if (!item.content) continue;

    for (const content of item.content) {

      if (
        content.type === "output_text" &&
        typeof content.text === "string"
      ) {
        response = content.text.trim();
        break;
      }

      if (
        content.text &&
        typeof content.text === "string"
      ) {
        response = content.text.trim();
        break;
      }
    }

    if (response) break;
  }
}

// 3. Fallback (older wrappers)
if (
  !response &&
  typeof $json.response === "string"
) {
  response = $json.response.trim();
}

// 4. Final fallback
if (!response) {
  response =
    "Lo siento, ocurrió un problema al generar la respuesta.";
}

return [
  {
    json: {
      assistant_response: response
    }
  }
];

/**
 * Extract assistant reply + next_action JSON
 * from an AI Agent output safely and reliably.
 */

const raw = $json.output || "";   // agent full output
const result = {
  assistant_message: "",
  next_action: "continue",         // default fallback
};

// ---------- 1. Extract JSON block safely ----------
let jsonMatch = raw.match(/\{[\s\S]*?\}/);

if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[0]);

    if (parsed.next_action === "subscription") {
      result.next_action = "subscription";
    } else {
      result.next_action = "continue";
    }
  } catch (err) {
    // malformed JSON → fallback
    result.next_action = "continue";
  }
} else {
  // No JSON found → fallback
  result.next_action = "continue";
}

// ---------- 2. Extract assistant human message ----------
result.assistant_message = raw
  .replace(/\{[\s\S]*?\}/, "")   // remove JSON block
  .trim();

// Safety fallback: if assistant_message becomes empty
if (!result.assistant_message) {
  result.assistant_message =
    "Gracias por tu mensaje 😊. ¿En qué puedo ayudarte?";
}

return result;

let raw = $input.first().json.output || '{}';
const validIntents = ['portal_help', 'program_help', 'recipe', 'meal_idea', 'restaurant_near', 'restaurant_menu', 'advice', 'support', 'general', 'unsubscribe'];
const validEntities = ['restaurant', 'neighborhood', 'city', 'region', 'ingredient', 'dish', 'meal_type', 'timeframe'];
const validProfileStatements = ['allergy', 'medical_condition', 'dislike', 'diet', 'name'];

try {
  const data = JSON.parse(raw);
  const intent = validIntents.includes(data.intent) ? data.intent : 'general';
  const confidence = Number.isFinite(Number(data.confidence))
    ? Math.min(1, Math.max(0, Number(data.confidence)))
    : 0;
  const entities = {};
  if (data.entities && typeof data.entities === 'object' && !Array.isArray(data.entities)) {
    for (const [rawKey, rawValue] of Object.entries(data.entities)) {
      const key = rawKey.toLowerCase().trim();
      if (!validEntities.includes(key)) continue;
      if (typeof rawValue === 'string') entities[key] = rawValue.trim();
      else if (Array.isArray(rawValue)) entities[key] = rawValue.filter((value) => typeof value === 'string').map((value) => value.trim());
    }
  }
  const profile_statement = validProfileStatements.includes(data.profile_statement)
    ? data.profile_statement
    : null;
  return [{ json: { intent, confidence, entities, profile_statement } }];
} catch {
  return [{ json: { intent: 'general', confidence: 0, entities: {}, profile_statement: null } }];
}

