parameters.jsCode:
const generationContext = $('Build Weekly Update Prompt').first().json;

let preparationContext = {};
try {
  preparationContext = $('Claim Due Next Week Preparation').item.json;
} catch {}

return [{
  json: {
    ...$json,
    program_id: generationContext.program_id || null,
    week_id: generationContext.week_id || null,
    week_number: preparationContext.week_number || (generationContext.week_id ? 1 : null)
  }
}];

const rawId = $json.body?.id;
const id = typeof rawId === 'string' ? rawId.trim() : '';
const valid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);

return [{
  json: {
    id: valid ? id : null,
    valid,
    generation_source: 'setup_webhook',
    is_async_request: true,
    error: valid ? null : 'A valid user id is required.'
  }
}];

const profile = $json.profile;
const preferences = profile && typeof profile === 'object' && !Array.isArray(profile)
  ? {
      diet: profile.eating_style || null,
      cuisine: null,
      allergies: Array.isArray(profile.allergies) ? [...profile.allergies] : [],
      dislikes: Array.isArray(profile.foods_to_avoid) ? [...profile.foods_to_avoid] : [],
      conditions: Array.isArray(profile.medical_conditions) ? [...profile.medical_conditions] : []
    }
  : { ...($json.preferences || {}) };
return [{ json: { ...$json, preferences } }];

return [{
  json: {
    success: true,
    created: false,
    program_id: $json.program_id,
    status: $json.status,
    generation_source: $json.generation_source || null,
    message: 'A program already exists for this subscriber.'
  }
}];

const context = $('Get New Program Week 1 Context').first().json;

return [{
  json: {
    success: true,
    created: true,
    program_id: $json.program_id,
    status: $json.status,
    start_date: $json.start_date,
    current_week: $json.current_week,
    generation_source: context.generation_source || null,
    is_async_request: context.is_async_request === true
  }
}];

const profile = $json.profile;

if (!profile) {
  return [{ json: $json }];
}

const list = (value) =>
  Array.isArray(value) && value.length
    ? value.join(', ')
    : 'No indicado';

const profileContext = `

Perfil de la usuaria para personalizar este plan:
- Mes de nacimiento: ${profile.birth_month ?? 'No indicado'}
- Año de nacimiento: ${profile.birth_year ?? 'No indicado'}
- Estatura: ${profile.height_cm ?? 'No indicado'} cm
- Peso: ${profile.weight_kg ?? 'No indicado'} kg
- Estilo de alimentación: ${profile.eating_style ?? 'No indicado'}
- Condiciones médicas: ${list(profile.medical_conditions)}
- Alergias: ${list(profile.allergies)}
- Alimentos a evitar: ${list(profile.foods_to_avoid)}
- Notas adicionales: ${profile.notes || 'No indicado'}

Respeta este perfil al seleccionar ingredientes y comidas. No inventes datos que no estén indicados.
`;

return [{
  json: {
    ...$json,
    prompt: `${$json.prompt}${profileContext}`
  }
}];

return [{
  json: {
    ...$json,
    generation_source: 'stripe',
    is_async_request: false
  }
}];

const event = $input.first().json || {};
const session = event?.data?.object || {};
const metadata = session.metadata || {};
const normalizeId = (value) => {
  if (value && typeof value === 'object') return value.id || '';
  return value == null ? '' : String(value);
};
const whatsappId = String(metadata.whatsapp_id ?? '')
  .trim()
  .replace(/^whatsapp:/i, '')
  .replace(/\s+/g, '')
  .trim();
const completedAt = Number.isFinite(Number(event.created))
  ? new Date(Number(event.created) * 1000).toISOString()
  : '';

return [{
  json: {
    event_id: normalizeId(event.id),
    checkout_session_id: normalizeId(session.id),
    mode: String(session.mode ?? '').toLowerCase(),
    payment_status: String(session.payment_status ?? '').toLowerCase(),
    payment_intent_id: normalizeId(session.payment_intent),
    customer_id: normalizeId(session.customer),
    email: String(session.customer_details?.email ?? '').trim().toLowerCase(),
    amount_total: Number.isFinite(Number(session.amount_total)) ? Number(session.amount_total) : null,
    currency: String(session.currency ?? '').toLowerCase(),
    whatsapp_id: whatsappId,
    user_id: String(metadata.user_id ?? '').trim(),
    acquisition_source: String(metadata.acquisition_source ?? 'whatsapp').trim().toLowerCase(),
    purchase_type: String(metadata.purchase_type ?? ''),
    program_version: String(metadata.program_version ?? ''),
    purchased_at: completedAt,
    raw_event: event
  }
}];

const data = $input.first().json;
const errors = [];
if (data.mode !== 'payment') errors.push('mode must be payment');
if (data.payment_status !== 'paid') errors.push('payment_status must be paid');
if (data.purchase_type !== '28_day_program') errors.push('purchase_type must be 28_day_program');
if (data.program_version !== '1') errors.push('program_version must be 1');
if (data.currency !== 'mxn') errors.push('currency must be mxn');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email || '') || data.email.length > 254) errors.push('Stripe customer email is required');
if (data.amount_total !== 14900) errors.push('amount_total must be 14900');
if (data.acquisition_source === 'website') {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(data.user_id || '')) {
    errors.push('canonical website user_id is required');
  }
  if (data.whatsapp_id) errors.push('website Checkout must not include whatsapp_id');
} else {
  if (data.acquisition_source !== 'whatsapp') errors.push('unsupported acquisition source');
  if (!data.whatsapp_id) errors.push('normalized whatsapp_id is required');
}
if (!data.checkout_session_id) errors.push('checkout_session_id is required');
if (!data.payment_intent_id) errors.push('payment_intent_id is required');
if (!data.purchased_at) errors.push('Stripe event completion time is required');

return [{ json: { ...data, validation_valid: errors.length === 0, validation_errors: errors } }];

const normalized = $('Normalize Stripe Checkout Event').item.json;
const response = $input.first().json || {};
const lineItems = Array.isArray(response.data) ? response.data : [];
const expectedPriceId = 'price_1U1QlXCVZMBOTTlaU1QD7FRT';
const item = lineItems.length === 1 ? lineItems[0] : null;
const price = item?.price || {};
const priceId = typeof price === 'string' ? price : price.id;
const product = typeof price === 'object' ? price.product : null;
const productId = typeof product === 'string' ? product : (product?.id || null);
const errors = [];

if (lineItems.length !== 1) errors.push('Checkout Session must contain exactly one line item');
if (priceId !== expectedPriceId) errors.push('Stripe Price ID does not match the 28-day program Price');
if (Number(item?.quantity) !== 1) errors.push('Checkout Session line-item quantity must be 1');

return [{
  json: {
    ...normalized,
    verified_price_id: priceId || '',
    verified_product_id: productId || '',
    price_validation_valid: errors.length === 0,
    validation_errors: errors
  }
}];

const data = $input.first().json;
const unsupported = data.mode !== 'payment' && data.mode !== 'subscription';
const errors = Array.isArray(data.validation_errors) ? data.validation_errors : [];
return [{
  json: {
    ...data,
    validation_errors: errors.length ? errors : [unsupported ? `unsupported Checkout Session mode: ${data.mode || '(empty)'}` : 'Stripe Checkout validation failed']
  }
}];

const classification = $('Parse JSON Intent and Entities').first().json;
const user = $('Get User from Supabase').first().json;
const context = $input.first().json;
const rawMessage = $('Claim Next Session Inbound').first().json.body || '';
const normalizedMessage = String(rawMessage).trim().replace(/\s+/g, ' ').normalize('NFC');
const simpleGeneral = classification.intent === 'general' && (
  classification.profile_statement !== null ||
  /^(hola|buen(?:os|as) (?:días|dias|tardes|noches)|gracias|muchas gracias|perfecto|ok|okay|listo|entendido)[.!¡¿? ]*$/i.test(normalizedMessage)
);

return [{ json: {
  user_id: user.id,
  user_message: normalizedMessage,
  raw_message: rawMessage,
  intent: classification.intent,
  confidence: classification.confidence,
  entities: classification.entities || {},
  profile_statement: classification.profile_statement || null,
  deterministic_general: simpleGeneral,
  portal_token_available: typeof user.portal_token === 'string' && user.portal_token.length > 0,
  program_status: context.program_status || null,
  program_start_date: context.program_start_date || null,
  current_week: context.current_week || null,
  program_duration_days: context.program_duration_days || 28,
  has_active_legacy_subscription: context.has_active_legacy_subscription === true,
  structured_profile: {
    eating_style: context.eating_style || null,
    allergies: Array.isArray(context.allergies) ? context.allergies : [],
    foods_to_avoid: Array.isArray(context.foods_to_avoid) ? context.foods_to_avoid : [],
    medical_conditions: Array.isArray(context.medical_conditions) ? context.medical_conditions : []
  }
} }];

const input = $input.first().json;
const user = $('Get User from Supabase').first().json;
const baseUrl = 'https://dietavity.com';
const portalUrl = input.portal_token_available ? baseUrl + '/p/' + user.portal_token : null;
const profileUrl = input.portal_token_available ? baseUrl + '/setup/' + user.portal_token : null;
const message = input.user_message || '';
const lower = message.toLocaleLowerCase('es-MX');
let assistant_response;

if (input.intent === 'unsubscribe') {
  assistant_response = 'Tu programa de 28 días es una compra única y no tiene una suscripción recurrente que cancelar. Si ves un cargo que no reconoces, escríbenos a soporte@dietavity.com.';
} else if (input.intent === 'portal_help') {
  if (!portalUrl) {
    assistant_response = 'No pude recuperar tu enlace de forma segura. Escríbenos a soporte@dietavity.com para ayudarte con el acceso.';
  } else if (/lista|súper|super|compras/.test(lower)) {
    assistant_response = 'Tu lista del súper está dentro de tu programa y se actualiza con tus comidas. Consúltala aquí: ' + portalUrl;
  } else if (/receta/.test(lower)) {
    assistant_response = 'Las recetas de las comidas incluidas en tu programa están aquí: ' + portalUrl;
  } else {
    assistant_response = 'Puedes consultar tu programa de 28 días aquí: ' + portalUrl;
  }
} else if (input.intent === 'program_help') {
  if (/otro plan|nuevo plan|plan de \d+ días|plan de \d+ dias|7 días|7 dias|plan semanal/.test(lower)) {
    assistant_response = 'Tu programa de 28 días se administra en el portal; no crearé un plan paralelo. Para cambiar una comida, abre tu programa y usa “No me gustó”.' + (portalUrl ? ' ' + portalUrl : '');
  } else if (/cu[aá]ndo|empieza|inicio|inicia/.test(lower)) {
    if (input.program_start_date) {
      const formatted = new Intl.DateTimeFormat('es-MX', { dateStyle: 'long', timeZone: 'UTC' }).format(new Date(input.program_start_date + 'T00:00:00Z'));
      assistant_response = 'Tu programa empieza el ' + formatted + '.' + (portalUrl ? ' Puedes verlo aquí: ' + portalUrl : '');
    } else if (input.program_status === 'personalization') {
      assistant_response = 'Tu programa aún está en preparación y todavía no tiene fecha de inicio confirmada. Te mostraremos el estado en el portal.' + (portalUrl ? ' ' + portalUrl : '');
    } else {
      assistant_response = 'No pude confirmar una fecha de inicio. Escríbenos a soporte@dietavity.com para revisarlo.';
    }
  } else if (/semana|siguiente/.test(lower)) {
    assistant_response = input.current_week
      ? 'Tu programa está en la semana ' + input.current_week + ' de 4.' + (portalUrl ? ' Revisa los detalles aquí: ' + portalUrl : '')
      : 'No pude confirmar tu semana actual. Escríbenos a soporte@dietavity.com para revisarlo.';
  } else if (/cu[aá]nto dura|duraci[oó]n|28 días|28 dias/.test(lower)) {
    assistant_response = 'El programa Dietavity dura 28 días, organizados en 4 semanas.';
  } else if (/cambi|reemplaz|no me gust[oó]/.test(lower)) {
    assistant_response = 'Para reemplazar una comida de tu programa, abre el portal y usa “No me gustó” en esa comida.' + (portalUrl ? ' ' + portalUrl : '');
  } else {
    const state = input.program_status ? ' El estado actual es “' + input.program_status + '”.' : '';
    assistant_response = 'Tu programa dura 28 días y está organizado en 4 semanas.' + state + (portalUrl ? ' Puedes consultarlo aquí: ' + portalUrl : '');
  }
} else if (input.intent === 'support') {
  assistant_response = 'Para ayuda de acceso, pagos o problemas técnicos, escríbenos a soporte@dietavity.com.' + (portalUrl ? ' Tu portal es: ' + portalUrl : '');
} else if (input.profile_statement === 'allergy') {
  assistant_response = 'Gracias por avisarme. No guardaré ni cambiaré tu programa automáticamente desde este chat. Evita ese alimento y actualiza tu perfil aquí para futuras semanas: ' + profileUrl + '. Si tienes síntomas o riesgo de una reacción, busca atención médica.';
} else if (input.profile_statement === 'medical_condition') {
